import { MeshStandardNodeMaterial } from 'three/webgpu';
import { color, uv, vec3, mix, smoothstep, float } from 'three/tsl';
import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-badge';

  const width = 1.1;
  const height = 0.34;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const tex = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  tex.colorSpace = THREE.SRGBColorSpace;

  const inkColor = color('#16161d');
  const accentColor = color('#ff2a38');

  const uvNode = uv();
  // edge light: distance from left/right edges
  const edgeDist = float(1.0).sub(smoothstep(0.0, 0.06, uvNode.x.oneMinus().min(uvNode.x)));
  const baseColor = mix(inkColor, vec3(tex), 0.35);
  const finalColor = mix(baseColor, accentColor, edgeDist.mul(0.85));

  const material = new MeshStandardNodeMaterial();
  material.colorNode = finalColor;
  material.metalness = 0.45;
  material.roughness = 0.55;
  material.clearcoat = 0.2;
  material.envMapIntensity = 1.0;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-collection-badge-mesh';
  group.add(mesh);

  group.position.set(0, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const baseScale = group.scale.clone();
  const baseY = group.position.y;

  let hoverTl = null;
  let pressTl = null;

  const handlers = {};

  handlers.onPointerOver = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  handlers.onPointerOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  handlers.onPointerDown = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: baseScale.x * 0.97,
      y: baseScale.y * 0.97,
      z: baseScale.z * 0.97,
      duration: 0.12,
      ease: 'back.out'
    });
  };

  handlers.onPointerUp = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: baseScale.x,
      y: baseScale.y,
      z: baseScale.z,
      duration: 0.12,
      ease: 'back.out'
    });
  };

  handlers.onClick = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-collection.select', { id: 'hub-collection-badge' });
    }
  };

  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    geometry.dispose();
    material.dispose();
    if (tex && tex.dispose) tex.dispose();
  };

  return group;
}
